"use client";

import "../../styles/teum-base.css";
import "../../styles/patterns/issues-workspace.css";
import {
  Archive,
  CalendarBlank,
  CheckCircle,
  Circle,
  Command,
  DotsThree,
  Plus,
  Rows,
  UserCircle,
} from "@phosphor-icons/react";
import { useEffect, useMemo, useState } from "react";
import { ActionList, type ActionListItem } from "../ui/action-list";
import { Badge } from "../ui/badge";
import { BulkActionBar } from "../ui/bulk-action-bar";
import { Button } from "../ui/button";
import { ColumnManager, DataToolbar, SavedViews } from "../ui/data-toolbar";
import { DataTable, type DataTableColumn } from "../ui/data-table";
import { Dialog, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "../ui/dialog";
import { FilterBuilder, type DataFilter, type FilterField } from "../ui/filter-builder";
import { IconButton } from "../ui/icon-button";
import { InlineEdit } from "../ui/inline-edit";
import { Menu, MenuContent, MenuItem, MenuLabel, MenuSeparator, MenuTrigger } from "../ui/menu";
import { SearchInput } from "../ui/search-input";
import { Select } from "../ui/select";
import { SharedDetail } from "../ui/shared-detail";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../ui/tabs";
import { TextField } from "../ui/text-field";
import { toast } from "../ui/toast";
import { UndoBar, UndoStackProvider, useUndoStack } from "../ui/undo-stack";

type PilotIssue = {
  id: string;
  code: string;
  title: string;
  description: string;
  status: "Backlog" | "In progress" | "Done";
  priority: "Low" | "Medium" | "High";
  assignee: string;
  updated: string;
};

const initialIssues: PilotIssue[] = [
  { id: "focus", code: "INT-204", title: "Unify keyboard focus", description: "Make focus movement predictable across menus, dialogs, and shared detail views.", status: "In progress", priority: "High", assignee: "Avery Stone", updated: "8m" },
  { id: "motion", code: "INT-198", title: "Tune shared detail motion", description: "Preserve list identity while detail content changes and adjacent issues are inspected.", status: "Backlog", priority: "Medium", assignee: "Mina Park", updated: "32m" },
  { id: "registry", code: "INT-191", title: "Verify registry consumer", description: "Install the public boundary into a clean app and record every generated dependency.", status: "Done", priority: "High", assignee: "Noah Williams", updated: "2h" },
  { id: "contrast", code: "INT-184", title: "Review dark theme contrast", description: "Check text, focus, disabled controls, and overlays in the cool graphite dark theme.", status: "Backlog", priority: "Low", assignee: "Avery Stone", updated: "1d" },
];

const statusOptions = ["Backlog", "In progress", "Done"].map((value) => ({ label: value, value }));
const priorityOptions = ["Low", "Medium", "High"].map((value) => ({ label: value, value }));
const proofSteps = [
  ["Find", "Filter issue"],
  ["Inspect", "Select row"],
  ["Act", "Archive via ⌘K"],
  ["Recover", "Choose Undo"],
] as const;

const filterFields: readonly FilterField[] = [
  { id: "status", label: "Status", values: statusOptions },
  { id: "priority", label: "Priority", values: priorityOptions },
  { id: "assignee", label: "Assignee", values: ["Avery Stone", "Mina Park", "Noah Williams", "Unassigned"].map((value) => ({ label: value, value })) },
];

const savedViews = [
  { id: "all", label: "All issues", description: "Every issue in the cycle" },
  { id: "active", label: "Active", description: "Backlog and in-progress work" },
  { id: "mine", label: "Assigned to me", description: "Issues owned by Avery Stone" },
  { id: "done", label: "Completed", description: "Finished work" },
] as const;

function PilotWorkspaceInner({ onReset }: { onReset: () => void }) {
  const [issues, setIssues] = useState(initialIssues);
  const [selectedId, setSelectedId] = useState<string | null>(initialIssues[0].id);
  const [query, setQuery] = useState("");
  const [filters, setFilters] = useState<readonly DataFilter[]>([]);
  const [savedView, setSavedView] = useState("all");
  const [selectedRowIds, setSelectedRowIds] = useState<readonly string[]>([]);
  const [columnVisibility, setColumnVisibility] = useState<Record<string, boolean>>({});
  const [createOpen, setCreateOpen] = useState(false);
  const [actionsOpen, setActionsOpen] = useState(false);
  const [proofStep, setProofStep] = useState(0);
  const [draftTitle, setDraftTitle] = useState("");
  const [draftDescription, setDraftDescription] = useState("");
  const { pushUndo } = useUndoStack();

  const filtered = useMemo(() => issues.filter((issue) => {
    const queryMatches = `${issue.code} ${issue.title} ${issue.status} ${issue.priority} ${issue.assignee}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase());
    const viewMatches = savedView === "all"
      || (savedView === "active" && issue.status !== "Done")
      || (savedView === "mine" && issue.assignee === "Avery Stone")
      || (savedView === "done" && issue.status === "Done");
    const filtersMatch = filters.every((filter) => {
      const candidate = String(issue[filter.fieldId as keyof PilotIssue]);
      return filter.operator === "is" ? candidate === filter.value : candidate !== filter.value;
    });
    return queryMatches && viewMatches && filtersMatch;
  }), [filters, issues, query, savedView]);
  const selected = issues.find((issue) => issue.id === selectedId);
  const sharedItems = filtered.map((issue) => ({ id: issue.id, title: issue.title, meta: `${issue.code} · ${issue.updated}`, description: issue.description, status: issue.status }));

  const dataColumns = useMemo<readonly DataTableColumn<PilotIssue>[]>(() => [
    {
      id: "issue",
      header: "Issue",
      accessor: (issue) => `${issue.code} ${issue.title}`,
      sortable: true,
      width: "38%",
      hideable: false,
      cell: (issue) => (
        <button type="button" className="pilot-table-link" onClick={() => selectIssue(issue.id)}>
          {issue.status === "Done" ? <CheckCircle aria-hidden="true" /> : <Circle aria-hidden="true" />}
          <span><strong>{issue.title}</strong><small>{issue.code}</small></span>
        </button>
      ),
    },
    {
      id: "status",
      header: "Status",
      accessor: "status",
      sortable: true,
      cell: (issue) => <Badge variant={issue.status === "Done" ? "strong" : "outline"}>{issue.status}</Badge>,
    },
    { id: "priority", header: "Priority", accessor: "priority", sortable: true },
    { id: "assignee", header: "Assignee", accessor: "assignee", sortable: true },
    { id: "updated", header: "Updated", accessor: "updated", align: "end", width: 72 },
  ], []);

  const viewCounts = useMemo(() => ({
    all: issues.length,
    active: issues.filter((issue) => issue.status !== "Done").length,
    mine: issues.filter((issue) => issue.assignee === "Avery Stone").length,
    done: issues.filter((issue) => issue.status === "Done").length,
  }), [issues]);

  const selectIssue = (id: string | null) => {
    setSelectedId(id);
    if (id) setProofStep((current) => Math.max(current, 2));
  };

  const actionItems = useMemo<readonly ActionListItem[]>(() => selected ? [
    { id: "toggle-status", label: selected.status === "Done" ? "Reopen issue" : "Mark issue done", description: `Update ${selected.code} without leaving the detail`, icon: selected.status === "Done" ? <Circle /> : <CheckCircle />, shortcut: "D" },
    { id: "priority", label: "Set high priority", description: `Move ${selected.code} to the active review queue`, icon: <Rows />, shortcut: "P" },
    { id: "archive", label: "Archive issue", description: "Remove it now and keep recovery available", icon: <Archive />, shortcut: "E", variant: "danger" },
  ] : [], [selected]);

  useEffect(() => {
    const openActions = (event: KeyboardEvent) => {
      if (!(event.metaKey || event.ctrlKey) || event.key.toLocaleLowerCase() !== "k" || !selected) return;
      event.preventDefault();
      setActionsOpen(true);
      setProofStep((current) => Math.max(current, 2));
    };
    window.addEventListener("keydown", openActions);
    return () => window.removeEventListener("keydown", openActions);
  }, [selected]);

  const updateIssue = (id: string, update: Partial<PilotIssue>) => setIssues((current) => current.map((issue) => issue.id === id ? { ...issue, ...update, updated: "Now" } : issue));

  const archiveIssue = (id: string, source: "menu" | "action-list" = "menu") => {
    const index = issues.findIndex((issue) => issue.id === id);
    const issue = issues[index];
    if (!issue) return;
    const remaining = issues.filter((item) => item.id !== id);
    setIssues(remaining);
    setSelectedId(remaining[Math.min(index, Math.max(remaining.length - 1, 0))]?.id ?? null);
    if (source === "action-list") setProofStep(3);
    pushUndo({
      label: `Archived ${issue.code}`,
      undo: () => {
        setIssues((current) => current.some((item) => item.id === issue.id) ? current : [...current.slice(0, index), issue, ...current.slice(index)]);
        setSelectedId(issue.id);
        if (source === "action-list") setProofStep(4);
      },
    });
  };

  const completeSelectedIssues = () => {
    const ids = new Set(selectedRowIds);
    if (!ids.size) return;
    setIssues((current) => current.map((issue) => ids.has(issue.id) ? { ...issue, status: "Done", updated: "Now" } : issue));
    setSelectedRowIds([]);
    toast(`${ids.size} ${ids.size === 1 ? "issue" : "issues"} completed`, { id: "pilot-feedback" });
  };

  const archiveSelectedIssues = () => {
    const ids = new Set(selectedRowIds);
    const archived = issues.filter((issue) => ids.has(issue.id));
    if (!archived.length) return;
    const previousIssues = issues;
    const remaining = issues.filter((issue) => !ids.has(issue.id));
    setIssues(remaining);
    setSelectedRowIds([]);
    if (selectedId && ids.has(selectedId)) setSelectedId(remaining[0]?.id ?? null);
    pushUndo({
      label: `Archived ${archived.length} ${archived.length === 1 ? "issue" : "issues"}`,
      undo: () => {
        setIssues(previousIssues);
        setSelectedId(archived[0]?.id ?? null);
      },
    });
  };

  const runAction = (item: ActionListItem) => {
    if (!selected) return;
    setActionsOpen(false);
    if (item.id === "toggle-status") {
      const nextStatus = selected.status === "Done" ? "In progress" : "Done";
      updateIssue(selected.id, { status: nextStatus });
      toast(nextStatus === "Done" ? "Issue completed" : "Issue reopened", { id: "pilot-feedback" });
    }
    if (item.id === "priority") {
      updateIssue(selected.id, { priority: "High" });
      toast("Priority updated", { id: "pilot-feedback", description: `${selected.code} is now high priority.` });
    }
    if (item.id === "archive") archiveIssue(selected.id, "action-list");
  };

  const createIssue = () => {
    const title = draftTitle.trim();
    if (!title) return;
    const next: PilotIssue = {
      id: `issue-${Date.now()}`,
      code: `INT-${206 + issues.length}`,
      title,
      description: draftDescription.trim() || "Add product context and acceptance criteria.",
      status: "Backlog",
      priority: "Medium",
      assignee: "Unassigned",
      updated: "Now",
    };
    setIssues((current) => [next, ...current]);
    setSelectedId(next.id);
    setDraftTitle("");
    setDraftDescription("");
    setCreateOpen(false);
    toast("Issue created", { id: "pilot-feedback", description: `${next.code} is ready for refinement.` });
  };

  return (
    <section className="pilot-workspace" aria-label="Issues Workspace">
      <header className="pilot-workspace__header">
        <div className="pilot-workspace__identity"><span><Rows aria-hidden="true" /></span><div><strong>Interface quality</strong><small>Cycle 08 · {issues.length} issues</small></div></div>
        <div className="pilot-workspace__actions">
          <SearchInput label="Search pilot issues" value={query} onChange={(event) => { setQuery(event.target.value); if (event.target.value.trim()) setProofStep((current) => Math.max(current, 1)); }} onClear={() => setQuery("")} placeholder="Search issues…" shortcut="/" />
          <Dialog open={actionsOpen} onOpenChange={(open) => { setActionsOpen(open); if (open) setProofStep((current) => Math.max(current, 2)); }}>
            <DialogTrigger render={<Button variant="secondary" size="small" leadingIcon={<Command />} aria-label="Open issue actions (Command K)">Actions</Button>} />
            <DialogContent className="pilot-action-dialog">
              <DialogHeader><DialogTitle>Act on {selected?.code ?? "selected issue"}</DialogTitle><DialogDescription>Find one action without losing the selected issue or its place in the list.</DialogDescription></DialogHeader>
              <ActionList items={actionItems} onAction={runAction} autoFocus placeholder="Search issue actions…" />
            </DialogContent>
          </Dialog>
          <Dialog open={createOpen} onOpenChange={setCreateOpen}>
            <DialogTrigger render={<Button variant="primary" size="small" leadingIcon={<Plus />} aria-label="New issue">New issue</Button>} />
            <DialogContent>
              <DialogHeader><DialogTitle>Create issue</DialogTitle><DialogDescription>Add a small, concrete piece of interface work to the active cycle.</DialogDescription></DialogHeader>
              <form className="pilot-create-form" onSubmit={(event) => { event.preventDefault(); createIssue(); }}>
                <TextField autoFocus label="Title" value={draftTitle} onChange={(event) => setDraftTitle(event.target.value)} placeholder="What needs attention?" />
                <TextField label="Description" value={draftDescription} onChange={(event) => setDraftDescription(event.target.value)} placeholder="Add useful context" />
                <DialogFooter><DialogClose render={<Button variant="ghost" />}>Cancel</DialogClose><Button type="submit" variant="primary" disabled={!draftTitle.trim()}>Create issue</Button></DialogFooter>
              </form>
            </DialogContent>
          </Dialog>
        </div>
      </header>

      <div className="pilot-proof" aria-label="Interaction proof task">
        <div><strong>Proof task</strong><span>Find → inspect → act → recover</span><button type="button" onClick={onReset}>Reset</button></div>
        <ol>{proofSteps.map(([label, description], index) => {
          const step = index + 1;
          return <li key={label} data-complete={proofStep >= step || undefined} aria-current={proofStep === index ? "step" : undefined}><span>{step}</span><div><strong>{label}</strong><small>{description}</small></div></li>;
        })}</ol>
      </div>

      <DataToolbar
        className="pilot-data-toolbar"
        label="Issue data controls"
        start={<>
          <SavedViews
            label="Saved views"
            views={savedViews.map((view) => ({ ...view, count: viewCounts[view.id] }))}
            value={savedView}
            onValueChange={setSavedView}
          />
          <FilterBuilder fields={filterFields} filters={filters} onFiltersChange={setFilters} />
        </>}
        end={<ColumnManager
          columns={dataColumns.map((column) => ({
            id: column.id,
            label: String(column.header),
            visible: columnVisibility[column.id] !== false,
            required: column.hideable === false,
          }))}
          onVisibilityChange={(id, visible) => setColumnVisibility((current) => ({ ...current, [id]: visible }))}
        />}
      />

      <Tabs defaultValue="issues" className="pilot-tabs">
        <div className="pilot-tabs__bar"><TabsList aria-label="Pilot views"><TabsTrigger value="issues">Issues</TabsTrigger><TabsTrigger value="cycle">Cycle</TabsTrigger></TabsList><span>{filtered.length} visible</span></div>
        <TabsContent value="issues" className="pilot-tabs__panel">
          {sharedItems.length ? <SharedDetail
            className="pilot-shared-detail"
            items={sharedItems}
            selectedId={filtered.some((issue) => issue.id === selectedId) ? selectedId : null}
            onSelectedIdChange={selectIssue}
            focusOnOpen={false}
            regionLabel="Selected issue detail"
            renderDetail={(item) => {
              const issue = issues.find((candidate) => candidate.id === item.id)!;
              return <div className="pilot-detail-content">
                <p>{issue.description}</p>
                <div className="pilot-detail-fields">
                  <Select label="Status" options={statusOptions} value={issue.status} onValueChange={(value) => updateIssue(issue.id, { status: value as PilotIssue["status"] })} />
                  <Select label="Priority" options={priorityOptions} value={issue.priority} onValueChange={(value) => updateIssue(issue.id, { priority: value as PilotIssue["priority"] })} />
                </div>
                <dl className="pilot-detail-meta"><div><dt><UserCircle aria-hidden="true" />Assignee</dt><dd>{issue.assignee}</dd></div><div><dt><CalendarBlank aria-hidden="true" />Updated</dt><dd>{issue.updated}</dd></div></dl>
                <div className="pilot-detail-title"><span>Title</span><InlineEdit value={issue.title} label="Edit issue title" onSave={(title) => updateIssue(issue.id, { title })} validate={(title) => title.length < 4 ? "Use at least four characters." : undefined} /></div>
                <div className="pilot-detail-actions"><Button size="small" variant="secondary" onClick={() => { updateIssue(issue.id, { status: issue.status === "Done" ? "In progress" : "Done" }); toast(issue.status === "Done" ? "Issue reopened" : "Issue completed", { id: "pilot-feedback" }); }}>{issue.status === "Done" ? "Reopen" : "Mark done"}</Button><Menu><MenuTrigger render={<IconButton size="small" variant="ghost" aria-label="More issue actions"><DotsThree /></IconButton>} /><MenuContent align="end"><MenuLabel>{issue.code}</MenuLabel><MenuItem onClick={() => updateIssue(issue.id, { priority: "High" })}>Set high priority</MenuItem><MenuSeparator /><MenuItem className="teum-menu__item--danger" onClick={() => archiveIssue(issue.id)}><Archive aria-hidden="true" />Archive issue</MenuItem></MenuContent></Menu></div>
              </div>;
            }}
          /> : <div className="pilot-empty"><strong>No matching issues</strong><p>Try a different query or create a new issue.</p><Button size="small" onClick={() => setQuery("")}>Clear search</Button></div>}
        </TabsContent>
        <TabsContent value="cycle" className="pilot-tabs__panel pilot-cycle">
          <DataTable
            ariaLabel="Active cycle issues"
            data={filtered}
            columns={dataColumns}
            getRowId={(issue) => issue.id}
            getRowLabel={(issue) => `${issue.code} ${issue.title}`}
            selectable
            selectedRowIds={selectedRowIds}
            onSelectedRowIdsChange={setSelectedRowIds}
            columnVisibility={columnVisibility}
            onColumnVisibilityChange={setColumnVisibility}
            defaultSorting={[{ id: "issue", direction: "asc" }]}
            pageSize={8}
            onRowActivate={(issue) => selectIssue(issue.id)}
            emptyTitle="No matching issues"
            emptyDescription="Change the active view, search, or filter."
          />
          <BulkActionBar
            count={selectedRowIds.length}
            noun="issue"
            onClear={() => setSelectedRowIds([])}
            actions={<>
              <Button size="small" variant="ghost" leadingIcon={<CheckCircle />} onClick={completeSelectedIssues}>Mark done</Button>
              <Button size="small" variant="ghost" leadingIcon={<Archive />} onClick={archiveSelectedIssues}>Archive</Button>
            </>}
          />
        </TabsContent>
      </Tabs>
      <UndoBar />
      <span className="teum-sr-only" aria-live="polite">{selected ? `${selected.code} selected` : "No issue selected"}</span>
    </section>
  );
}

export function IssuesWorkspace() {
  const [run, setRun] = useState(0);
  return <UndoStackProvider key={run}><PilotWorkspaceInner onReset={() => setRun((current) => current + 1)} /></UndoStackProvider>;
}

export const ProductPilot = IssuesWorkspace;

export type TeumDataComponentContract = {
  id: string;
  intent: string;
  useWhen: readonly string[];
  avoidWhen: readonly string[];
  requires: readonly string[];
  states: readonly string[];
  compositionRules: readonly string[];
  accessibility: readonly string[];
};

export const teumDataComponentContracts = [
  {
    id: "data-table",
    intent: "Compare and act on structured records without hiding the underlying table semantics.",
    useWhen: ["Rows share comparable attributes.", "Sorting, selection, or bounded pagination supports a real task."],
    avoidWhen: ["Records have no meaningful shared columns.", "A short list or cards communicate the content more directly."],
    requires: ["Stable row ids", "Human-readable row labels", "Column labels", "Loading, empty, and error copy"],
    states: ["default", "sorted", "selected", "loading", "empty", "error"],
    compositionRules: ["Search and filters sit outside the table model.", "Bulk actions appear only after selection.", "Details preserve the selected row identity."],
    accessibility: ["Use semantic table markup.", "Give selection controls record-specific names.", "Expose sort direction with aria-sort."],
  },
  {
    id: "filter-builder",
    intent: "Turn a small set of categorical conditions into visible, removable query clauses.",
    useWhen: ["People need to combine a few known fields.", "Every active condition should remain visible."],
    avoidWhen: ["The query language is free-form or deeply nested.", "One select can express the whole choice."],
    requires: ["Field labels", "Finite values", "A controlled filter state"],
    states: ["empty", "editing", "active", "duplicate replacement", "cleared"],
    compositionRules: ["Keep active clauses next to the trigger.", "Replace an identical field/operator pair instead of duplicating it.", "Do not hide active filters inside the flyout."],
    accessibility: ["Announce additions and removals.", "Keep the trigger available after a clause is added.", "Return focus to the trigger when the flyout closes."],
  },
  {
    id: "data-toolbar",
    intent: "Keep view, search, filter, and display controls in one compact product boundary.",
    useWhen: ["Several controls operate on the same collection."],
    avoidWhen: ["A single search field is the only collection control."],
    requires: ["A primary collection label", "Start and end control groups"],
    states: ["default", "wrapped", "active query"],
    compositionRules: ["Task controls precede display controls.", "The toolbar may wrap without changing control order.", "Keyboard hints never shrink or wrap."],
    accessibility: ["Label the toolbar by collection task.", "Preserve DOM order when the toolbar wraps."],
  },
  {
    id: "bulk-action-bar",
    intent: "Expose actions that apply to the current selection without moving the collection.",
    useWhen: ["Two or more records can receive the same reversible action."],
    avoidWhen: ["The action needs record-by-record confirmation.", "Nothing is selected."],
    requires: ["Selection count", "At least one action", "A clear-selection path"],
    states: ["hidden", "visible", "busy", "error"],
    compositionRules: ["Overlay or reserve space so the table does not jump.", "Place destructive actions after neutral actions.", "Use Undo for reversible completion."],
    accessibility: ["Announce the selection count.", "Keep focus stable after an action.", "Give clear-selection an explicit label."],
  },
] as const satisfies readonly TeumDataComponentContract[];

export const issuesWorkspaceContract = {
  id: "issues-workspace",
  intent: "Find, compare, inspect, mutate, and recover work from one shared issue collection.",
  taskSequence: ["Search or filter", "Sort and compare", "Select records", "Inspect one record", "Act", "Undo when needed"],
  components: ["DataToolbar", "SavedViews", "FilterBuilder", "DataTable", "ColumnManager", "BulkActionBar", "SharedDetail", "ActionList", "UndoStack"],
  invariants: [
    "Search, filters, table, details, and actions share one source of truth.",
    "Selection never changes table geometry.",
    "Opening detail preserves the selected row and collection position.",
    "Reversible mutations enter the same undo history.",
    "Keyboard and pointer paths complete the same task.",
  ],
} as const;

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.pilot-workspace {
  position: relative;
  margin-top: 20px;
  overflow: hidden;
  border: 1px solid var(--teum-control-border);
  border-radius: 11px;
  background: var(--teum-bg-surface);
  box-shadow: 0 18px 52px color-mix(in oklch, var(--teum-fg-default) 6%, transparent);
}

.pilot-workspace--loading {
  display: grid;
  min-height: 360px;
  place-items: center;
  color: var(--teum-fg-subtle);
  font-size: var(--teum-type-ui);
}

.pilot-workspace__header {
  display: flex;
  min-height: 58px;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 9px 11px 9px 14px;
  border-bottom: 1px solid var(--teum-separator);
  background: color-mix(in oklch, var(--teum-bg-surface) 86%, transparent);
}

.pilot-workspace__identity { display: flex; min-width: 0; align-items: center; gap: 9px; }

.pilot-workspace__identity > span {
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 7px;
  background: var(--teum-inverse);
  color: var(--teum-on-inverse);
}

.pilot-workspace__identity svg { width: 14px; height: 14px; }

.pilot-workspace__identity > div { display: grid; gap: 1px; min-width: 0; }

.pilot-workspace__identity strong { overflow: hidden; color: var(--teum-fg-default); font-size: var(--teum-type-ui); font-weight: 590; text-overflow: ellipsis; white-space: nowrap; }

.pilot-workspace__identity small { color: var(--teum-fg-subtle); font-size: var(--teum-type-metadata); }

.pilot-workspace__actions { display: flex; align-items: center; gap: 7px; }

.pilot-workspace__actions .teum-search-field { width: 208px; }

.pilot-workspace__actions .teum-search { height: 30px; background: var(--teum-bg-subtle); }

.pilot-create-form { display: grid; gap: 14px; margin-top: 18px; }

.pilot-create-form .teum-dialog__footer { margin-top: 4px; }

.pilot-action-dialog { width: min(520px, calc(100vw - 32px)); }

.pilot-action-dialog .teum-action-list { width: 100%; margin-top: 16px; box-shadow: none; }

.pilot-proof { display: grid; gap: 10px; padding: 12px 14px 14px; background: var(--teum-bg-stage); }

.pilot-proof > div { display: flex; min-width: 0; align-items: center; gap: 8px; }

.pilot-proof > div strong { color: var(--teum-fg-default); font-size: var(--teum-type-label); font-weight: 590; }

.pilot-proof > div span { min-width: 0; overflow: hidden; color: var(--teum-fg-subtle); font-size: var(--teum-type-metadata); text-overflow: ellipsis; white-space: nowrap; }

.pilot-proof > div button { margin-left: auto; padding: 0; border: 0; background: transparent; color: var(--teum-fg-muted); font: inherit; font-size: var(--teum-type-metadata); cursor: pointer; }

.pilot-proof > div button:hover { color: var(--teum-fg-default); }

.pilot-proof ol { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; margin: 0; padding: 0; list-style: none; }

.pilot-proof li { display: grid; grid-template-columns: 20px minmax(0, 1fr); min-height: 46px; align-items: center; gap: 7px; padding: 6px 7px; border-radius: 7px; color: var(--teum-fg-subtle); }

.pilot-proof li[aria-current="step"] { background: var(--teum-bg-control); color: var(--teum-fg-default); box-shadow: inset 0 0 0 1px var(--teum-separator); }

.pilot-proof li[data-complete] { color: var(--teum-fg-muted); }

.pilot-proof li > span { display: grid; width: 20px; height: 20px; place-items: center; border-radius: 999px; background: var(--teum-bg-control); color: inherit; font-size: var(--teum-type-metadata); font-variant-numeric: tabular-nums; }

.pilot-proof li[data-complete] > span { background: var(--teum-inverse); color: var(--teum-on-inverse); }

.pilot-proof li > div { display: grid; min-width: 0; gap: 1px; }

.pilot-proof li strong { font-size: var(--teum-type-metadata); font-weight: 590; }

.pilot-proof li small { overflow: hidden; color: inherit; font-size: var(--teum-type-metadata); text-overflow: ellipsis; white-space: nowrap; }

.pilot-data-toolbar {
  min-height: 46px;
  padding: 7px 12px;
  background: var(--teum-bg-surface);
}

.pilot-tabs { gap: 0; }

.pilot-tabs__bar {
  display: flex;
  min-height: 45px;
  align-items: center;
  justify-content: space-between;
  padding: 7px 12px;
  border-bottom: 1px solid var(--teum-separator);
}

.pilot-tabs__bar .teum-tabs__list { border: 0; background: var(--teum-bg-subtle); }

.pilot-tabs__bar > span { color: var(--teum-fg-subtle); font-size: var(--teum-type-metadata); }

.pilot-tabs__panel { min-height: 440px; padding: 12px; }

.pilot-shared-detail { min-height: 416px; border: 0; border-radius: 7px; background: var(--teum-bg-stage); }

.pilot-shared-detail[data-open] { grid-template-columns: minmax(250px, .88fr) minmax(360px, 1.12fr); }

.pilot-shared-detail .teum-shared-detail__list { padding: 7px; }

.pilot-shared-detail .teum-shared-detail__row { min-height: 61px; padding-inline: 10px; }

.pilot-shared-detail .teum-shared-detail__row[aria-expanded="true"] { background: var(--teum-selected); }

.pilot-shared-detail .teum-shared-detail__panel { background: var(--teum-bg-surface); }

.pilot-shared-detail .teum-shared-detail__content { padding: 22px 24px 26px; }

.pilot-detail-content > p { margin: 13px 0 20px; }

.pilot-detail-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }

.pilot-detail-fields .teum-field { min-width: 0; }

.pilot-detail-meta { margin-top: 16px !important; }

.pilot-detail-meta dt { display: inline-flex; align-items: center; gap: 6px; }

.pilot-detail-meta dt svg { width: 12px; height: 12px; }

.pilot-detail-title { display: grid; gap: 4px; margin-top: 16px; }

.pilot-detail-title > span { color: var(--teum-fg-subtle); font-size: var(--teum-type-metadata); }

.pilot-detail-title .teum-inline-edit { min-height: 36px; }

.pilot-detail-title .teum-inline-edit__value,
.pilot-detail-title .teum-inline-edit__input { height: 36px; padding-inline: 8px; font-size: var(--teum-type-ui); font-weight: 560; letter-spacing: -.018em; }

.pilot-detail-actions { display: flex; align-items: center; justify-content: space-between; margin-top: 18px; }

.pilot-empty { display: grid; min-height: 392px; place-content: center; justify-items: center; gap: 6px; color: var(--teum-fg-muted); text-align: center; }

.pilot-empty strong { color: var(--teum-fg-default); font-size: var(--teum-type-ui); }

.pilot-empty p { margin: 0 0 8px; font-size: var(--teum-type-label); }

.pilot-cycle { position: relative; overflow-x: auto; }

.pilot-cycle .teum-table__container { border: 0; box-shadow: none; }

.pilot-cycle .teum-table { min-width: 620px; }

.pilot-cycle > .teum-bulk-action-bar {
  position: sticky;
  z-index: var(--teum-layer-float);
  bottom: 10px;
  width: fit-content;
  max-width: calc(100% - 20px);
  margin: 10px auto 0;
}

.pilot-table-link { display: inline-flex; min-width: 0; align-items: center; gap: 8px; padding: 0; border: 0; background: transparent; color: var(--teum-fg-default); text-align: left; cursor: pointer; }

.pilot-table-link > svg { width: 14px; height: 14px; flex: 0 0 auto; color: var(--teum-fg-muted); }

.pilot-table-link > span { display: grid; gap: 1px; min-width: 0; }

.pilot-table-link strong { overflow: hidden; max-width: 260px; font-size: var(--teum-type-label); font-weight: 560; text-overflow: ellipsis; white-space: nowrap; }

.pilot-table-link small { color: var(--teum-fg-subtle); font-size: var(--teum-type-metadata); }

.pilot-workspace > .teum-undo-bar {
  position: fixed;
  z-index: var(--teum-layer-toast);
  right: auto;
  bottom: 18px;
  left: calc(50% + 31px);
  width: min(344px, calc(100vw - 32px));
  translate: -50% 0;
}

@media (max-width: 900px) {
.pilot-workspace__actions .teum-search-field { width: 168px; }

.pilot-shared-detail[data-open] { grid-template-columns: minmax(210px, .8fr) minmax(300px, 1.2fr); }
}

@media (max-width: 720px) {
.pilot-workspace__header { align-items: stretch; flex-direction: column; }

.pilot-workspace__actions { width: 100%; }

.pilot-workspace__actions .teum-search-field { width: auto; flex: 1; }

.pilot-workspace__actions .teum-button__content > span:last-child { display: none; }

.pilot-workspace__actions .teum-button { width: 30px; padding-inline: 0; }

.pilot-proof ol { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.pilot-data-toolbar { align-items: stretch; }

.pilot-tabs__panel { min-height: 470px; padding: 8px; }

.pilot-shared-detail[data-open] { grid-template-columns: 1fr; }

.pilot-shared-detail[data-open] .teum-shared-detail__list { display: none; }

.pilot-shared-detail .teum-shared-detail__panel { border-left: 0; }

.pilot-shared-detail .teum-shared-detail__back { display: inline-flex; margin-right: auto; }
}

@media (prefers-reduced-motion: reduce) {
.pilot-workspace { transition-duration: .01ms; }
}

@media (max-width: 1180px) {
.pilot-workspace > .teum-undo-bar { left: calc(50% + 119px); }
}

@media (max-width: 820px) {
.pilot-workspace > .teum-undo-bar { left: 50%; }
}
}
